Source code in <code>src/python/ensembl/genes/rgb/io.py</code> <pre><code>def write_df(df: pd.DataFrame, path: str, fmt: str = "tsv") -&gt; None:
    ensure_dir(os.path.dirname(path))
    fmt = fmt.lower()
    if fmt == "parquet":
        if not _can_parquet():
            fmt = "tsv"
        else:
            df.to_parquet(path, index=False)
            return
    if fmt == "tsv":
        df.to_csv(path, sep="\t", index=False)
    elif fmt == "csv":
        df.to_csv(path, index=False)
    else:
        raise ValueError(f"Unsupported format: {fmt}")
